  // ── Screen: collections ────────────────────────────────────────────────────
  'help.ctx.collections.title': 'คอลเลกชัน',
  'help.ctx.collections.summary':
    'คอลเลกชัน คือคลังสถานที่ของคุณที่อยู่นอกทริป: รายการที่ตั้งชื่อไว้ของสถานที่ที่คุณพบและอยากเก็บไว้ แต่ละสถานที่มีสถานะ ไอเดีย อยากไป หรือ เยี่ยมชมแล้ว สถานที่จะถูกคัดลอกเข้าและออกจากทริป ไม่ได้เชื่อมโยงกัน รายการและทริปจึงไม่เปลี่ยนแปลงกันและกัน',
