  'help.guide.create-place.tip.2':
    'ดัชนีของ TREK และ OpenStreetMap ให้ผลการค้นหาบน TREK ทุกแห่ง และ รายละเอียดสถานที่ จะดึงข้อมูลจาก Wikipedia, Wikivoyage และ Wikimedia โดยอัตโนมัติ ระบบจะถาม Google เฉพาะเมื่อทั้งสองแหล่งไม่มีผลลัพธ์ และมีเพียง Google ที่ให้คะแนนรีวิว',
  'help.guide.create-place.tip.3': 'เริ่มสร้างสถานที่จากแผนที่ก็ได้ คลิกขวาที่จุดนั้น ฟอร์มจะเปิดขึ้นพร้อมพิกัดและที่อยู่ที่กรอกไว้แล้ว',
  // place-to-open-day
