  'help.guide.import-places-file.goal': 'นำเข้าข้อมูลที่ส่งออกจาก Google My Maps, Google Earth หรืออุปกรณ์ติดตาม GPS',
  'help.guide.import-places-file.step.1': 'คลิก นำเข้าไฟล์ หรือวางไฟล์ที่ใดก็ได้บนคอลัมน์สถานที่',
