  'help.guide.import-places-file.tip.1': 'ไฟล์ที่ใหญ่เกินไปจะถูกปฏิเสธพร้อมแจ้งขนาดสูงสุด ให้ส่งออกใหม่โดยไม่มีรูปภาพ หรือแบ่งไฟล์',
