  'help.guide.import-places-list.result': 'ทุกสถานที่ในรายการจะอยู่ในทริป โดยใช้ชื่อเดียวกับในรายการ ส่วนสถานที่ที่อยู่ในทริปแล้วจะถูกข้าม',
  'help.guide.import-places-list.tip.1': 'รายการต้องแชร์แบบสาธารณะ ลิงก์ของรายการส่วนตัวจะไม่นำเข้าสิ่งใด',
