  'help.guide.export-plan.goal': 'นำแผนติดตัวไปในรูปแบบเอกสาร ลงในปฏิทิน หรือลงในอุปกรณ์ GPS',
  'help.guide.export-plan.step.1': 'คลิก ส่งออก ในแถบเครื่องมือเหนือรายการวัน',
