  'help.guide.rate-place.tip.1': 'นักเดินทางทุกคนให้คะแนนได้ แม้ในทริปที่มีเพียงบางคนเท่านั้นที่แก้ไขสถานที่ได้',
  'help.guide.rate-place.tip.2': 'คลิกดาวที่คุณให้ไว้แล้วเพื่อถอนคะแนน เมื่อไม่มีใครโหวตเหลืออยู่ สถานที่จะแสดง ยังไม่ได้รับการจัดอันดับ อีกครั้ง',
  'help.guide.rate-place.tip.3': 'รูปโปรไฟล์ผู้โหวตแสดงข้างดาวได้สูงสุดหกคน คำแนะนำเครื่องมือจะระบุชื่อทุกคนและทำเครื่องหมายของคุณไว้',
