  'help.guide.place-image.step.3': 'ส่วนหัวจะแสดงรูปภาพของคุณ พร้อม X สีแดงเล็กๆ ที่มุม',
  'help.guide.place-image.step.4': 'รูปภาพเดียวกันจะอยู่บนแถวของสถานที่ในคอลัมน์สถานที่ และบนหมุดบนแผนที่',
  'help.guide.place-image.result': 'รูปภาพของคุณจะเป็นรูปของสถานที่ทุกที่ ทั้งในการ์ด คอลัมน์สถานที่ จุดแวะในวัน หมุดบนแผนที่ และทริปที่แชร์',
  'help.guide.place-image.tip.1': 'รองรับ JPG, PNG, GIF และ WebP ส่วน HEIC จาก iPhone จะถูกแปลงระหว่างอัปโหลด',
