  'help.guide.place-day-assign.step.3': 'คลิก เพิ่มไปยังวัน จุดแวะจะถูกเพิ่มท้ายวัน และปุ่มจะเปลี่ยนเป็น ลบออกจากวัน',
  'help.guide.place-day-assign.step.4': 'จุดแวะอยู่ในวันแล้ว เป็นรายการสุดท้าย ลากขึ้นไปยังตำแหน่งที่ต้องการ',
