  'help.guide.place-day-assign.result': 'วันจะมีหรือไม่มีจุดแวะนั้น และไม่ว่าอย่างไรตัวสถานที่ก็ไม่ได้รับผลกระทบ',
  'help.guide.place-day-assign.tip.1': 'ปุ่มนี้มีเฉพาะเมื่อเปิดวันอยู่ หากไม่มีวันที่เปิดอยู่ การ์ดก็ไม่มีที่ให้เพิ่มสถานที่',
  'help.guide.place-day-assign.tip.2': 'การนำจุดแวะออกจากวันยังคงเก็บสถานที่ไว้ในทริปและในคอลัมน์สถานที่ ลบ เท่านั้นที่ลบสถานที่ออกจากทุกที่',
