  'help.guide.change-transit-route.tip.2': 'ลบ ที่ด้านล่างของการเดินทางจะนำเส้นทางออกจากทริป ส่วนวันยังคงมีจุดแวะเหมือนเดิม',
  // leg-travel-mode
