  'help.guide.leg-travel-mode.step.3': 'คลิกตัวเชื่อม เมนูจะมี ขับรถ และ เดิน, การขนส่งสาธารณะ และ ใช้ค่าเริ่มต้นของวัน',
  'help.guide.leg-travel-mode.step.4': 'เลือก เดิน เฉพาะช่วงนี้ที่เปลี่ยน ส่วนที่เหลือของวันยังคงใช้วิธีของตัวเอง',
  'help.guide.leg-travel-mode.result': 'ช่วงนั้นแสดงไอคอนเท้าและเวลาเดิน และช่วงอื่นๆ ของวันยังคงใช้วิธีของวัน',
